package com.sisi.health.engine

/** Deterministic text red-flag detection (en/sw/sheng), run BEFORE any LLM
 * (spec 5.2). The urgent-care script is always generated by these patterns plus
 * the hotline config — an LLM is never in the loop for it. Mirrors the backend
 * matcher semantics: any hit in an urgent category forces the urgent script;
 * safeguarding categories route to the safeguarding lead, never a guardian. */
class RedFlagMatcher(patternFiles: List<RedFlagPatternFile>) {

    private data class Compiled(
        val regex: Regex,
        val id: String,
        val category: String,
        val urgency: String,
    )

    private val patterns: List<Compiled> = patternFiles.flatMap { file ->
        file.patterns.map { entry ->
            Compiled(Regex(entry.regex, RegexOption.IGNORE_CASE), entry.id, entry.category, entry.urgency)
        }
    }

    data class Hit(val patternId: String, val category: String, val urgency: String)

    fun matchText(text: String): List<Hit> = patterns.mapNotNull { compiled ->
        if (compiled.regex.containsMatchIn(text)) {
            Hit(compiled.id, compiled.category, compiled.urgency)
        } else {
            null
        }
    }

    /** urgent: red-flag text always shows the urgent-care script first (spec 3.3).
     * safeguarding: routes to the safeguarding lead, NEVER a guardian alert. */
    fun escalations(hits: List<Hit>): Escalations = Escalations(
        urgent = hits.any { it.category in URGENT_CATEGORIES },
        safeguarding = hits.any { it.category in SAFEGUARDING_CATEGORIES },
    )

    data class Escalations(val urgent: Boolean, val safeguarding: Boolean)

    companion object {
        val URGENT_CATEGORIES =
            setOf(
                "severe_acute_pain",
                "heavy_bleeding_dizziness",
                "self_harm",
                // Cervical-screening red flags (spec 5.4.1): parity with the backend
                // matcher — abnormal bleeding/discharge always shows the urgent script.
                "postcoital_bleeding",
                "intermenstrual_bleeding",
                "postmenopausal_bleeding",
                "unusual_discharge",
            )
        val SAFEGUARDING_CATEGORIES =
            setOf("self_harm", "abuse_signal", "pregnancy_concern_minor", "guardian_risk")
    }
}
